#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later
#
# Fedora 44 repository-isolation scenarios against REAL dnf5.
#
# Two local file:// repositories stand in for Fedora and the lionheartp/Hyprland COPR (same
# repository ID format as `dnf5 copr enable`). The override is generated by the repository's own
# code (bin/zackos repo show-override, from the real manifest), so this tests the production
# artifact, not a copy of it. Dummy noarch RPMs are built on the fly. The real Fedora repos are
# moved away after the tooling is installed, so nothing here can reach the network.
set -u
# shellcheck source=tests/dnf5/common.sh
source "$(dirname -- "${BASH_SOURCE[0]}")/common.sh"
ci_guard

ID="copr:copr.fedorainfracloud.org:lionheartp:Hyprland"
SPEC="lionheartp/Hyprland"
FEDORA_DIR=/srv/fedora-sim
COPR_DIR=/srv/copr-sim
OVERRIDE_DIR=/etc/dnf/repos.override.d
OVERRIDE_FILE="${OVERRIDE_DIR}/50-zackos-isolation-lionheartp-Hyprland.repo"
export ZACKOS_ROOT="" ZACKOS_STATE_DIR=/tmp/zackos-state NO_COLOR=1
DNF=(dnf5 -y --refresh)

echo "== tooling"
dnf5 --version | head -3
dnf5 -y install rpm-build createrepo_c >/dev/null || {
    echo "cannot install tooling" >&2
    exit 1
}

# ---- dummy packages
build_rpm() { # dir name version [requires...]
    local dir="$1" name="$2" ver="$3" top reqs="" r
    shift 3
    for r in "$@"; do reqs+="Requires: ${r}"$'\n'; done
    top="$(mktemp -d)"
    mkdir -p "${top}"/{SPECS,RPMS,BUILD,SOURCES,SRPMS}
    cat >"${top}/SPECS/${name}.spec" <<SPEC
Name: ${name}
Version: ${ver}
Release: 1
Summary: dummy ${name} for ZackOS CI
License: GPL-3.0-or-later
BuildArch: noarch
${reqs}
%description
Dummy package used only by the ZackOS Fedora 44 CI isolation scenarios.
%install
mkdir -p %{buildroot}/usr/share/zackos-ci
echo "${name}-${ver}" > %{buildroot}/usr/share/zackos-ci/${name}
%files
/usr/share/zackos-ci/${name}
SPEC
    rpmbuild -bb --quiet --define "_topdir ${top}" "${top}/SPECS/${name}.spec" >/dev/null || return 1
    mkdir -p "${dir}"
    cp "${top}"/RPMS/noarch/*.rpm "${dir}/"
    rm -rf "${top}"
}
publish() { createrepo_c --quiet "$1" >/dev/null; }

mkdir -p "${FEDORA_DIR}" "${COPR_DIR}"
for p in kitty zsh fastfetch waybar; do build_rpm "${FEDORA_DIR}" "${p}" 1.0; done
build_rpm "${FEDORA_DIR}" zt-fedora-dep 1.0
# COPR: allowlisted packages, a dependency that is NOT allowlisted, and packages that must never win.
build_rpm "${COPR_DIR}" hyprland 2.0 zt-fedora-dep
build_rpm "${COPR_DIR}" xdg-desktop-portal-hyprland 2.0 hyprland
build_rpm "${COPR_DIR}" uwsm 2.0 zt-unlisted-lib
build_rpm "${COPR_DIR}" zt-unlisted-lib 2.0
build_rpm "${COPR_DIR}" kitty 99.0
build_rpm "${COPR_DIR}" zsh 99.0
build_rpm "${COPR_DIR}" waybar-git 9.0
build_rpm "${COPR_DIR}" hyprland-git 9.0
build_rpm "${COPR_DIR}" zt-other 1.0
publish "${FEDORA_DIR}"
publish "${COPR_DIR}"

# ---- repo configuration: real repos moved away, simulated ones added
mkdir -p /root/real-repos
mv /etc/yum.repos.d/*.repo /root/real-repos/ 2>/dev/null || true
write_fedora_repo() {
    cat >/etc/yum.repos.d/fedora-sim.repo <<REPO
[fedora]
name=Fedora simulation
baseurl=file://${FEDORA_DIR}
enabled=1
gpgcheck=0
REPO
}
write_copr_repo() {
    cat >"/etc/yum.repos.d/_copr:copr.fedorainfracloud.org:lionheartp:Hyprland.repo" <<REPO
[${ID}]
name=Copr repo for Hyprland owned by lionheartp (simulation)
baseurl=file://${COPR_DIR}
enabled=1
gpgcheck=0
REPO
}
write_override() { # generated by the production code, from the real manifest
    mkdir -p "${OVERRIDE_DIR}"
    bash "${REPO_ROOT}/bin/zackos" repo show-override >"${OVERRIDE_FILE}"
}
reset_pkgs() { dnf5 -y remove kitty zsh fastfetch waybar hyprland xdg-desktop-portal-hyprland uwsm zt-fedora-dep zt-unlisted-lib zt-other >/dev/null 2>&1 || true; }
installed_origin() { # uses the production helper against real dnf5 + rpm
    # shellcheck source=lib/dnf.sh
    (source "${REPO_ROOT}/lib/dnf.sh"; dnf_installed_origin "$1")
}
installed_ver() { rpm -q --qf '%{VERSION}' "$1" 2>/dev/null; }
is_installed() { rpm -q "$1" >/dev/null 2>&1; }

write_fedora_repo
write_copr_repo
rm -f "${OVERRIDE_FILE}"

echo
echo "== S0 negative control: WITHOUT the override the COPR really does win (setup is able to detect the problem)"
"${DNF[@]}" install kitty >/dev/null 2>&1
if [[ "$(installed_ver kitty)" == "99.0" ]]; then
    record "S0 control: no override => COPR kitty wins" PASS "(proves the test can detect a leak)"
else
    record "S0 control: no override => COPR kitty wins" FAIL "got version '$(installed_ver kitty)'; the scenarios below would prove nothing"
fi
reset_pkgs

write_override
echo "-- generated override:"
sed 's/^/   | /' "${OVERRIDE_FILE}"

echo
echo "== S1 override is accepted by dnf5 and applied"
check "S1a dnf5 loads the override without errors" bash -c "dnf5 -y --refresh repoquery --available >/dev/null 2>/tmp/err && ! grep -qiE 'error|invalid|unknown' /tmp/err"
avail="$(dnf5 -q repoquery --available --repo "${ID}" --queryformat '%{name}\n' 2>/dev/null | sort -u | tr '\n' ' ')"
echo "   COPR visible names: ${avail}"
if [[ "${avail}" == "hyprland uwsm xdg-desktop-portal-hyprland " ]]; then
    record "S1b COPR exposes exactly the allowlist" PASS
else
    record "S1b COPR exposes exactly the allowlist" FAIL "visible: ${avail}"
fi

echo
echo "== S2 same package offered by Fedora and COPR: Fedora must win"
"${DNF[@]}" install kitty zsh >/dev/null 2>&1
if [[ "$(installed_ver kitty)" == "1.0" && "$(installed_ver zsh)" == "1.0" ]]; then record "S2a kitty/zsh come from Fedora (1.0, not 99.0)" PASS; else record "S2a kitty/zsh come from Fedora (1.0, not 99.0)" FAIL "kitty=$(installed_ver kitty) zsh=$(installed_ver zsh)"; fi
if [[ "$(installed_origin kitty)" == "fedora" ]]; then record "S2b from_repo query tag reports the repo id" PASS; else record "S2b from_repo query tag reports the repo id" FAIL "origin='$(installed_origin kitty)' (dnf_installed_origin contract needs a fix)"; fi
if [[ "$(bash -c "source ${REPO_ROOT}/lib/dnf.sh; dnf_origin_class \"\$(dnf_installed_origin kitty)\"")" == "fedora" ]]; then record "S2c origin classified as fedora" PASS; else record "S2c origin classified as fedora" FAIL; fi

echo
echo "== S3 allowlisted COPR packages install, with their COPR dependency chain"
"${DNF[@]}" install xdg-desktop-portal-hyprland >/dev/null 2>&1
if is_installed hyprland && is_installed xdg-desktop-portal-hyprland; then
    if [[ "$(installed_origin hyprland)" == "${ID}" && "$(installed_origin xdg-desktop-portal-hyprland)" == "${ID}" ]]; then record "S3a allowlisted packages install from the COPR" PASS; else record "S3a allowlisted packages install from the COPR" FAIL "origins: $(installed_origin hyprland) / $(installed_origin xdg-desktop-portal-hyprland)"; fi
else
    record "S3a allowlisted packages install from the COPR" FAIL "not installed"
fi
if [[ "$(installed_origin zt-fedora-dep)" == "fedora" ]]; then record "S3b non-COPR dependency resolved from Fedora" PASS; else record "S3b non-COPR dependency resolved from Fedora" FAIL "origin=$(installed_origin zt-fedora-dep)"; fi
if (source "${REPO_ROOT}/lib/dnf.sh"; source "${REPO_ROOT}/lib/repo.sh"; dnf_all_installed_origins | repo_audit "${SPEC}"); then
    record "S3c repo audit finds no violation" PASS
else
    record "S3c repo audit finds no violation" FAIL
fi

echo
echo "== S4 forbidden packages cannot be installed"
for target in kitty-99.0 zt-other hyprland-git waybar-git zt-unlisted-lib; do
    "${DNF[@]}" install "${target}" >/dev/null 2>&1
    name="${target%-99.0}"
    if [[ "${name}" == kitty ]]; then
        bad=0
        [[ "$(installed_ver kitty)" == "99.0" ]] && bad=1
    else
        bad=0
        is_installed "${name}" && bad=1
    fi
    if ((bad)); then record "S4 forbidden: install ${target}" FAIL; else record "S4 forbidden: install ${target}" PASS; fi
done
out="$(dnf5 -y --refresh install --repo "${ID}" kitty 2>&1)"
if [[ "$(installed_ver kitty)" == "99.0" ]]; then
    record "S4 forbidden: install kitty restricted to the COPR repo" FAIL
elif grep -qiE 'unknown argument|unrecognized|invalid option' <<<"${out}"; then
    record "S4 forbidden: install kitty restricted to the COPR repo" SKIP "dnf5 rejected --repo: ${out%%$'\n'*}"
else
    record "S4 forbidden: install kitty restricted to the COPR repo" PASS
fi

echo
echo "== S5 COPR dependency that is not allowlisted"
reset_pkgs
"${DNF[@]}" install uwsm >/dev/null 2>&1
if is_installed uwsm || is_installed zt-unlisted-lib; then
    record "S5a dnf5 refuses a package whose COPR dependency is not allowlisted" FAIL "uwsm=$(is_installed uwsm && echo yes || echo no)"
else
    record "S5a dnf5 refuses a package whose COPR dependency is not allowlisted" PASS
fi
if printf 'uwsm\tzt-unlisted-lib\t%s\n' "${ID}" | (source "${REPO_ROOT}/lib/dnf.sh"; source "${REPO_ROOT}/lib/repo.sh"; repo_closure_gaps "${SPEC}" hyprland uwsm xdg-desktop-portal-hyprland) | grep -q '^GAP'; then
    record "S5b closure check reports the gap before installing" PASS
else
    record "S5b closure check reports the gap before installing" FAIL
fi

echo
echo "== S6 normal upgrades"
"${DNF[@]}" install kitty hyprland >/dev/null 2>&1
build_rpm "${FEDORA_DIR}" kitty 1.1
build_rpm "${COPR_DIR}" hyprland 2.1 zt-fedora-dep
build_rpm "${COPR_DIR}" kitty 100.0
publish "${FEDORA_DIR}"
publish "${COPR_DIR}"
"${DNF[@]}" upgrade >/dev/null 2>&1
if [[ "$(installed_ver kitty)" == "1.1" && "$(installed_origin kitty)" == "fedora" ]]; then record "S6a upgrade: kitty -> Fedora 1.1, not COPR 100.0" PASS; else record "S6a upgrade: kitty -> Fedora 1.1, not COPR 100.0" FAIL "kitty=$(installed_ver kitty) from $(installed_origin kitty)"; fi
if [[ "$(installed_ver hyprland)" == "2.1" && "$(installed_origin hyprland)" == "${ID}" ]]; then record "S6b upgrade: allowlisted hyprland -> COPR 2.1" PASS; else record "S6b upgrade: allowlisted hyprland -> COPR 2.1" FAIL "hyprland=$(installed_ver hyprland)"; fi

echo
echo "== S7 downgrade and version skew"
"${DNF[@]}" downgrade kitty >/dev/null 2>&1
if [[ "$(installed_ver kitty)" == "1.0" && "$(installed_origin kitty)" == "fedora" ]]; then record "S7a downgrade of a Fedora package stays in Fedora" PASS; else record "S7a downgrade of a Fedora package stays in Fedora" FAIL "kitty=$(installed_ver kitty) from $(installed_origin kitty)"; fi
# Fedora later ships a package that is also allowlisted from the COPR: highest version wins.
build_rpm "${FEDORA_DIR}" hyprland 3.0 zt-fedora-dep
publish "${FEDORA_DIR}"
"${DNF[@]}" upgrade >/dev/null 2>&1
echo "   hyprland after Fedora ships 3.0: version=$(installed_ver hyprland) origin=$(installed_origin hyprland)"
if [[ "$(installed_ver hyprland)" == "3.0" ]]; then
    record "S7b INFO Fedora 3.0 supersedes COPR 2.1 (highest version wins)" PASS "origin=$(installed_origin hyprland); acceptable, audit must not flag it"
else
    record "S7b INFO Fedora 3.0 supersedes COPR 2.1 (highest version wins)" FAIL "hyprland=$(installed_ver hyprland)"
fi
if (source "${REPO_ROOT}/lib/dnf.sh"; source "${REPO_ROOT}/lib/repo.sh"; dnf_all_installed_origins | repo_audit "${SPEC}"); then
    record "S7c audit after skew: no violation" PASS
else
    record "S7c audit after skew: no violation" FAIL
fi
rm -f "${FEDORA_DIR}"/hyprland-3.0-1.noarch.rpm
publish "${FEDORA_DIR}"

echo
echo "== S8 history list and undo (rollback is manual, never automatic)"
reset_pkgs
"${DNF[@]}" install xdg-desktop-portal-hyprland >/dev/null 2>&1
tid="$(dnf5 history list 2>/dev/null | awk '$1 ~ /^[0-9]+$/ {print $1}' | sort -n | tail -1)"
echo "   last transaction id: ${tid:-none}"
if [[ -n "${tid}" ]] && dnf5 -y history undo "${tid}" >/tmp/undo.out 2>&1; then
    if ! is_installed xdg-desktop-portal-hyprland && ! is_installed hyprland; then
        record "S8 dnf5 history undo removes exactly that transaction" PASS
    else
        record "S8 dnf5 history undo removes exactly that transaction" FAIL "packages still installed"
    fi
else
    record "S8 dnf5 history undo removes exactly that transaction" FAIL "$(tail -3 /tmp/undo.out 2>/dev/null)"
fi

echo
echo "== S9 override written BEFORE the repository exists, repo ID containing colons"
rm -f "/etc/yum.repos.d/_copr:copr.fedorainfracloud.org:lionheartp:Hyprland.repo"
reset_pkgs
write_override
write_copr_repo
"${DNF[@]}" install kitty >/dev/null 2>&1
if [[ "$(installed_ver kitty)" == "1.0" || "$(installed_ver kitty)" == "1.1" ]]; then record "S9 override applies when written before the repo" PASS; else record "S9 override applies when written before the repo" FAIL "kitty=$(installed_ver kitty)"; fi

echo
echo "== S10 disabling the repo leaves the override in place and the system consistent"
sed -i 's/^enabled=1/enabled=0/' "/etc/yum.repos.d/_copr:copr.fedorainfracloud.org:lionheartp:Hyprland.repo"
"${DNF[@]}" upgrade >/dev/null 2>&1
if [[ -f "${OVERRIDE_FILE}" ]] && is_installed kitty; then record "S10 disabled repo: override kept, no breakage" PASS; else record "S10 disabled repo: override kept, no breakage" FAIL; fi
sed -i 's/^enabled=0/enabled=1/' "/etc/yum.repos.d/_copr:copr.fedorainfracloud.org:lionheartp:Hyprland.repo"

echo
echo "== S11 PackageKit"
record "S11 PackageKit" SKIP "not testable in a container (no systemd/D-Bus). NOT claimed as tested; on-device check deferred until COPR is approved"

finish "Fedora 44 repository isolation (real dnf5)"
